        "1 Enoch (Ethiopian tradition) (-200).",
        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Book of the Watchers (1 Enoch 1-36)</em> <small>(c. 200 BC)</small><p>1 Enoch opens with a programmatic blessing &#x27;which Enoch blessed the elect and righteous, who will be living in the day of tribulation, when all the wicked and godless are to be removed&#x27; (Charles 1912 trans.). The opening immediately establishes the book&#x27;s apocalyptic-eschatological orientation: it is written for the persecuted righteous of a future tribulation, not as historical narrative but as prophetic vision. The Tewahedo canonical reception locates this opening alongside the Pentateuchal openings as setting the entire revelatory horizon — the Mäṣḥafä Hēnok is read liturgically in Tewahedo Lenten cycles precisely for this eschatological orientation.</p></aside>',
