        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Book of the Watchers (1 Enoch 1-36)</em> <small>(c. 200 BC)</small><p>&#x27;The Holy Great One will come forth from His dwelling, and the eternal God will tread upon the earth, even on Mount Sinai, and appear in the strength of His might from the heaven of heavens&#x27; — the Sinai theophany extended to a general theological pattern. The God who once came down on Sinai will come again at the eschaton; the historical theophany prefigures the eschatological. The Tewahedo Synaxarium readings for the Feast of the Transfiguration explicitly connect this verse to the Tabor manifestation: each visible coming of the Most High to creation participates in the one cosmic visitation that the Mäṣḥafä Hēnok foretells.</p></aside>',
