        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Book of the Watchers (1 Enoch 1-36)</em> <small>(c. 200 BC)</small><p>&#x27;Behold, He cometh with ten thousands of His saints to execute judgment upon all, and to destroy all the ungodly&#x27; is the verse the New Testament Jude 1:14-15 quotes VERBATIM, attributing it to &#x27;Enoch, the seventh from Adam&#x27;. Jude&#x27;s canonical-NT quotation of 1 Enoch as inspired prophecy is the strongest textual basis for the Tewahedo canon&#x27;s reception of 1 Enoch as Scripture — if Jude treats 1 Enoch as prophetic Word, the Tewahedo argues, the rest of the Church should at least not deny what an apostle affirmed. This verse is therefore THE textual bridge between 1 Enoch and the canonical New Testament.</p></aside>',
