        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Book of the Watchers (1 Enoch 1-36)</em> <small>(c. 200 BC)</small><p>&#x27;Observe ye everything that takes place in the heaven, how they do not change their orbits, and the luminaries which are in the heaven, how they all rise and set in order, each in its season, and transgress not against their appointed order&#x27; — the natural-theology argument from cosmic regularity. The Watchers&#x27; rebellion is precisely the violation of this divinely-appointed cosmic order; the natural creation&#x27;s obedience shames the angelic-human disobedience. The Tewahedo monastic tradition draws explicit catechetical use: the unfailing observance of natural creation rebukes the failing observance of moral creation.</p></aside>',
