        "Note",
        "Note",
        """<strong>The recapitulation.</strong> The chapter rounds off the four-chapter argument from natural phenomena (chs 2–5): cosmic luminaries, seasons, evergreens, summer sun — and now the productive cycle of trees in spring, leafing and fruiting. The recapitulation prepares the moral application that follows immediately (5:4, "ye have not been steadfast"). The structure is rhetorically calibrated: pile up evidence of cosmic obedience first, then turn to human moral failure. The same pattern of nature-evidence-followed-by-moral-application recurs throughout wisdom literature (Prov 6:6–11, the ant; Prov 30:24–28, the four small wise things) and informs the broader Second Temple wisdom-pedagogical tradition. 1 Enoch’s deployment is unusually expansive — four chapters of cosmic evidence before the application — and the expansion gives the moral charge its considerable weight.""",
