        "ye have not been steadfast",
        "comm",
        "Note",
        "Note",
        """<strong>The moral indictment.</strong> The chapter’s climactic accusation against the unrighteous — "ye have not been steadfast, nor done the commandments of the Lord, but have turned away and spoken proud and hard words with your impure mouths against His greatness" — is the entire prior natural-theological argument applied. The cosmic luminaries were steadfast; the seasons were steadfast; humans were not. The vocabulary is theologically precise: the Aramaic <em>ša‘adin</em> ("steadfast") and Greek <em>emeinate</em> resonate with the broader Second Temple ethics of <em>steadfastness</em> as core covenantal virtue (cf. James 1:12, "blessed is the man who endures temptation"; the recurring NT theme of <em>hypomonē</em>, "endurance"). The verse functions as a hinge in 1 Enoch’s opening: from cosmic observation (chs 2–5) the argument now turns to the cosmic violation that has produced the present disorder — the Watchers’ rebellion (chs 6–11). The moral diagnosis is delivered before the historical-mythological cause is narrated.""",
