        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Book of the Watchers (1 Enoch 1-36)</em> <small>(c. 200 BC)</small><p>&#x27;But ye — ye have not been steadfast, nor done the commandments of the Lord&#x27; — the address to the unrighteous after the natural-theology argument of chs 2-5. The transgression is specifically of the COMMANDMENTS, not of vague moral sensibility: 1 Enoch presupposes the Mosaic covenant as the standard by which the elect are measured. The Tewahedo reading takes this as the canonical Jewish covenant-theology basis that the Christian moral catechesis presupposes; the Sermon on the Mount intensifies but does not abrogate the prior commanded standard.</p></aside>',
