        "1 Enoch (Ethiopian tradition) (-200).",
        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Book of the Watchers (1 Enoch 1-36)</em> <small>(c. 200 BC)</small><p>&#x27;But to the elect there shall be light and joy and peace, and they shall inherit the earth&#x27; — the climactic blessing on the righteous, anticipating the Beatitude &#x27;Blessed are the meek, for they shall inherit the earth&#x27; (Mt 5:5 = Ps 37:11). The triple gift (light + joy + peace) Tewahedo eschatology reads as the proper inheritance of the resurrection saints: not merely escape from suffering but positive participation in divine glory. The &#x27;inherit the earth&#x27; is read in Tewahedo eschatology as the new-creation earth, restored and glorified, not the present fallen earth.</p></aside>',
