        "1 Enoch (Ethiopian tradition) (-200).",
        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Book of the Watchers (1 Enoch 1-36)</em> <small>(c. 200 BC)</small><p>&#x27;It came to pass when the children of men had multiplied that in those days were born unto them beautiful and comely daughters. And the angels, the children of the heaven, saw and lusted after them&#x27; — the foundational Watcher narrative that expands Genesis 6:1-4. Two hundred angels under Semjâzâ descend on Mount Hermon and bind themselves by oath to take human wives, knowing the act is forbidden. The Tewahedo reading takes this not as mythological folklore but as actual cosmic-historical rebellion: the disordering of the angelic order is the proximate cause of the disordering of the human order that necessitates the Flood. This is the Tewahedo canonical anchor that distinguishes its angelology from those of other Christian traditions.</p></aside>',
