        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Book of the Watchers (1 Enoch 1-36)</em> <small>(c. 200 BC)</small><p>&#x27;And the angels, the children of the heaven, saw and lusted after them, and said to one another: Come, let us choose us wives from among the children of men and beget us children&#x27; — the deliberate-collective character of the Watchers&#x27; decision. The rebellion is not impulsive individual passion but coordinated council: &#x27;said to one another&#x27; frames the sin as conspiratorial, not accidental. The Tewahedo angelological tradition reads this against any reading that would minimize Satan-and-the-fallen-angels as mere temptation-creatures: they are genuine moral agents with developed plans, not impulsive nature-spirits.</p></aside>',
