        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Book of the Watchers (1 Enoch 1-36)</em> <small>(c. 200 BC)</small><p>&#x27;Then sware they all together and bound themselves by mutual imprecations upon it&#x27; — the angelic oath that seals the rebellion. The mutual binding-by-oath ensures no individual angel can retreat from the collective plan: each is now bound to all the others. Tewahedo demonological tradition reads this as the prototype of every subsequent secret-society oath: the binding-by-mutual-imprecation is the demonic technology for ensuring collective evil endures past individual second-thoughts. The verse warrants a deep ascetic suspicion of any oath-bound association outside the Church&#x27;s sacramental order.</p></aside>',
