        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Book of the Watchers (1 Enoch 1-36)</em> <small>(c. 200 BC)</small><p>&#x27;And they were in all two hundred; who descended in the days of Jared on the summit of Mount Hermon&#x27; — the precise location and numbering of the Watchers&#x27; descent. Mount Hermon in northern Israel (the headwaters of the Jordan) becomes for the Tewahedo tradition the geographical inverse of Mount Sinai: Sinai is where God descends to give the Law; Hermon is where the rebellious angels descend to disorder creation. The Mäṣḥafä Hēnok dating in the days of Jared (Enoch&#x27;s father) places the rebellion seven generations after Adam — the moral entropy of the post-fall world accelerating until Noah.</p></aside>',
