        "1 Enoch (Ethiopian tradition) (-200).",
        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Book of the Watchers (1 Enoch 1-36)</em> <small>(c. 200 BC)</small><p>&#x27;And they became pregnant, and they bare great giants, whose height was three thousand ells&#x27; — the Nephilim of Genesis 6:4 here named explicitly as the half-angelic offspring of the Watchers&#x27; union with human women. The &#x27;three thousand ells&#x27; (vastly hyperbolic — Charles notes the Greek tradition has lower numbers) signals the disordered scale of the offspring: not merely large humans but a different ontological category, neither fully angelic nor fully human. The Tewahedo theological reading takes this as the prototype of every subsequent demonic infestation: the half-creatures that issue from forbidden union belong to no created order and find their proper place only in destruction.</p></aside>',
