        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Book of the Watchers (1 Enoch 1-36)</em> <small>(c. 200 BC)</small><p>&#x27;The giants turned against them and devoured mankind. And they began to sin against birds, and beasts, and reptiles, and fish, and to devour one another&#x27;s flesh, and drink the blood&#x27; — the violent escalation of giant predation. The four-fold catalog (humans / birds / beasts / fish) traces the giant predation through the whole creaturely order; &#x27;devour one another&#x27;s flesh&#x27; makes them ultimately self-cannibalistic. Tewahedo monastic-ascetic tradition reads this as the ultimate pattern of disordered appetite: unchecked consumption finally turns inward, devouring its own. The catalog itself becomes the textual basis for the standard four-fold dietary categories preserved in monastic fasting rules.</p></aside>',
