        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Book of the Watchers (1 Enoch 1-36)</em> <small>(c. 200 BC)</small><p>&#x27;Azâzêl taught men to make swords, and knives, and shields, and breastplates&#x27; — the Watchers&#x27; second crime: teaching humans forbidden technologies that enable violence and seduction. The catalog continues with metallurgy, cosmetics, sorcery, astrology, weather magic, root-cutting, and astronomical secrets. The Tewahedo reading takes this as the prototype of every subsequent technology-corrupted-by-fallen-knowledge: the technologies themselves are not evil, but their introduction by rebel angels (rather than by the proper covenantal tradition) makes them weapons of disorder rather than tools of stewardship. This is the textual root of the Tewahedo monastic ascetic suspicion of certain technological luxuries.</p></aside>',
