        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Book of the Watchers (1 Enoch 1-36)</em> <small>(c. 200 BC)</small><p>&#x27;And as men perished, they cried, and their cry went up to heaven&#x27; — the foundational text for the prayer-of-the-oppressed as cosmic-judicial appeal. The &#x27;cry&#x27; (Geez &#x27;awyāt) is involuntary lament of those suffering injustice; it ascends to heaven by divine ordinance, not by deliberate liturgical mediation. This is the textual basis for the Tewahedo doctrine of God&#x27;s predisposition to hear the cry of the persecuted regardless of formal liturgical observance: oppression itself becomes prayer when borne by the innocent.</p></aside>',
