        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Book of the Watchers (1 Enoch 1-36)</em> <small>(c. 200 BC)</small><p>&#x27;Then Michael, Uriel, Raphael, and Gabriel looked down from heaven and saw much blood being shed upon the earth&#x27; — the four-archangel intercession that responds to the cry of the oppressed. The four names establish the canonical Tewahedo angelology: Michael (warrior-defender), Uriel (light-bearer / scribe), Raphael (healer / binder of Azazel), Gabriel (messenger). Other Christian traditions know one or two of these; the Tewahedo Synaxarium honors all four with dedicated feast days, drawing the angelological framework directly from this Enochic chapter.</p></aside>',
