        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Book of the Watchers (1 Enoch 1-36)</em> <small>(c. 200 BC)</small><p>The archangels address the Most High: &#x27;Lord of lords, God of gods, King of kings, and God of the ages, the throne of Thy glory standeth unto all the generations of the ages, and Thy name holy and glorious and blessed unto all the ages&#x27; — the foundational angelic doxology. The triple superlative (Lord of lords + God of gods + King of kings) becomes the Tewahedo liturgical model for naming God in the Anaphora prayers; &#x27;King of kings&#x27; specifically (mèngèshte negus) becomes the Ethiopian imperial title (Negus Negesti = King of Kings) borrowed from this verse. The Tewahedo Anaphora of the Apostles preserves this Enochic doxology pattern verbatim.</p></aside>',
