        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Book of the Watchers (1 Enoch 1-36)</em> <small>(c. 200 BC)</small><p>&#x27;And they have gone to the daughters of men upon the earth, and have slept with the women, and have defiled themselves&#x27; — the archangels&#x27; formal indictment of the Watchers. The verb &#x27;defiled themselves&#x27; (Geez &#x27;irat) Tewahedo reads not merely as ritual impurity but as ontological self-degradation: the Watchers&#x27; descent into human sexuality reduces their angelic substance to a corrupted mixed-state. This grounds the Tewahedo monastic-ascetic theology of celibacy: not because sexuality is evil (Gen 1:28 stands) but because angelic-ranked existence has always been celibate by nature, and the monastic call is to anticipate that angelic mode of life.</p></aside>',
