        "Note",
        "Note",
        """<strong>The aromatic east.</strong> Enoch’s tour now turns east of the cosmic center, into a region of fragrant trees and plants — beginning what becomes a sustained catalog of aromatic specimens (chs 28–32). The geographical orientation reflects ancient Mediterranean-Levantine assumptions about the eastern provenance of incense and exotic spices (cf. the wise men "from the east" bringing frankincense and myrrh in Matt 2:11, drawing on the same eastern-aromatic geographical-mythological tradition). The chapters’ aromatic geography is partly real-economic (Arabian frankincense, Indian cinnamon, etc., did reach the Mediterranean from the east) and partly mythologically idealized (paradisal eastern regions in the imaginative geography of the period). 1 Enoch’s catalog draws on this shared imaginative space and converts it into theological geography.""",
