        "Note",
        "Note",
        """<strong>Frankincense and myrrh.</strong> The two named aromatics — frankincense (Hebrew <em>levonah</em>) and myrrh (<em>mor</em>) — are the most theologically loaded specimens in the OT incense-economy. Frankincense was a required ingredient in the sacred incense (Exod 30:34); myrrh was an ingredient in the holy anointing oil (Exod 30:23). Both were among the most expensive trade goods of the ANE. The NT presents them at Christ’s nativity (Matt 2:11) and at his burial (John 19:39, Nicodemus’ myrrh-and-aloes mixture for embalming) as the framing aromatics of his earthly mission. 1 Enoch’s placement of these specifically named aromatics in the eschatological-paradisal landscape registers their theological weight: they are not just expensive luxuries but the substance-stuff of holy worship. The verse encodes one of the small but significant continuities between Second Temple cosmological imagination and NT Christological symbolism.""",
