        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Book of the Watchers (1 Enoch 1-36)</em> <small>(c. 200 BC)</small><p>&#x27;And I saw the trees of judgement, especially vessels of the fragrance of frankincense and myrrh, and the trees were not like each other&#x27; — Enoch&#x27;s vision of the aromatic trees of paradise: frankincense and myrrh prominent among them. The same two substances are brought as gifts to the infant Christ (Mt 2:11) — Tewahedo Christological reading takes the Magi gifts as proleptic offering from the eschatological paradise back to the Incarnate one whose advent inaugurates the new creation. The Tewahedo eucharistic preparation includes frankincense + myrrh in deliberate liturgical-cosmic reference.</p></aside>',
