        "Note",
        "Note",
        """<strong>Cinnamon in apocalyptic geography.</strong> Cinnamon (<em>Cinnamomum verum</em>) is one of the longest-traded ANE luxury aromatics, sourced originally from Sri Lanka and southern India and reaching the Mediterranean via Arabian intermediaries from at least the second millennium BCE. Its cost made it a marker of luxury (cf. Prov 7:17, "I have perfumed my bed with myrrh, aloes, and cinnamon"; Song 4:14, the lover’s garden including cinnamon; Rev 18:13, the trade-cargo of fallen Babylon including "cinnamon, and odors, and ointments"). The chapter’s mention is one of 1 Enoch’s moments where actual spice-trade geography enters apocalyptic vision: the cinnamon Enoch sees growing in eastern paradisal regions corresponds, mythologically transformed, to the real Indian-Sri Lankan cinnamon reaching Levantine markets. The chapter participates in a wider cultural imagination linking the eastern paradise with the eastern source of expensive aromatics, an imaginative geography that informs Magi traditions and NT iconography directly.""",
