        "Note",
        "Note",
        """<strong>The supreme fragrance.</strong> The chapter ends with a small superlative — the burnt resin smelled "sweeter than any fragrant odour." The construction is one of 1 Enoch’s recurrent rhetorical devices: cumulatively superlative descriptions register cosmic-eschatological excess, where each item is more than the previous. The same rhetorical pattern recurs at 14:18 (Yahweh’s throne "more brilliant than the sun"), 24:4 (the fragrant tree with "fragrance beyond all fragrance"), and elsewhere. The cumulative effect is theologically purposeful: the apocalyptic landscape exceeds anything human experience contains, and ordinary descriptive language strains under the weight. The verse is one of many small markers of the genre’s self-understanding — apocalyptic vision is not merely informative but performatively stretches the categories the seer has available, communicating the otherness of the cosmic-eschatological order through linguistic excess.""",
