        "1 Enoch (Ethiopian tradition) (-200).",
        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Book of the Watchers (1 Enoch 1-36)</em> <small>(c. 200 BC)</small><p>&#x27;And I came to the Garden of Righteousness, and saw beyond those trees many large trees growing there and of goodly fragrance, large, very beautiful and glorious, and the tree of wisdom whereof they eat and know great wisdom&#x27; — Enoch reaches the Edenic Garden of Righteousness with the tree of wisdom (distinct from the tree of life at 24:4 and 25:5). The Garden of Righteousness as the proper-name designation of restored Eden becomes determinative for Tewahedo monastic-spiritual literature: the monastery is figured as the proleptic Garden of Righteousness on earth, where the tree of wisdom yields its fruit to the disciplined ascetic.</p></aside>',
