        "Note",
        "Note",
        """<strong>The stellar portals.</strong> Enoch’s reported counting of the heavenly portals through which the stars proceed introduces the technical-astronomical theology that the Astronomical Book (chs 72–82) will systematize. The portal-theory of stellar appearance — that stars enter and exit visible heaven through fixed gates at the eastern and western horizon — is consistent with Babylonian astronomical theory of the period (cf. the MUL.APIN tablets, mid-second millennium BCE) and represents 1 Enoch’s integration of ANE technical astronomy with apocalyptic theology. The verse functions as bridge to the Astronomical Book’s detailed material; the seer’s function as cosmic surveyor includes recording technical-astronomical detail, treating the mathematical-observational data of star-positions as theologically significant. The chapter encodes one of 1 Enoch’s most distinctive theological-cosmological commitments: the rationality of cosmic order is itself revelation.""",
