        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Book of the Watchers (1 Enoch 1-36)</em> <small>(c. 200 BC)</small><p>&#x27;And there I saw the ends of the earth whereon the heaven rests, and the portals of the heaven open. And I saw how the stars of heaven come forth, and I counted the portals out of which they proceed&#x27; — Enoch&#x27;s vision of the cosmological mechanism by which stars rise and set. The &#x27;portals&#x27; (Geez bāʾəw) are gates in the heavenly dome through which the heavenly bodies pass on their appointed circuits. Tewahedo theological cosmology preserves this gateway-cosmology in its liturgical hymnody: the doxologies frequently reference the &#x27;portals of heaven&#x27; through which prayers ascend and divine gifts descend.</p></aside>',
