        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Book of the Watchers (1 Enoch 1-36)</em> <small>(c. 200 BC)</small><p>&#x27;And from thence I went towards the north to the ends of the earth, and there I saw a great and glorious device at the ends of the whole earth&#x27; — Enoch&#x27;s northward journey reaches the cosmic north device. The &#x27;great and glorious device&#x27; (Geez maxbar &#x27;abiy wa-səbuh) Tewahedo cosmological tradition reads as the divine mechanism for weather: the storehouses of snow, rain, and wind from which the meteorological phenomena are dispatched per divine will. This pre-meteorological cosmology Tewahedo monasticism preserves as catechetical resource: weather is not merely natural but divinely-administered, and prayer for rain is real petition to the administering Most High.</p></aside>',
