        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Book of the Watchers (1 Enoch 1-36)</em> <small>(c. 200 BC)</small><p>&#x27;And from thence I went to the south to the ends of the earth, and saw there three open portals of the heaven: from them issues dew, rain, and wind&#x27; — Enoch&#x27;s final journey-segment to the south completes the four-directional cosmological survey (chs 17-36). Together with the earlier western (17-19) and northern (34) journeys + the central Jerusalem-omphalos vision (26-32), Enoch has now mapped the cosmic geography from all four cardinal directions. The Tewahedo iconographic tradition&#x27;s depictions of the cosmos often preserve this four-directional structuring with Jerusalem at the center, drawing on the Enochic cosmological survey as authoritative source.</p></aside>',
