        "Note",
        """<strong>The stellar courses.</strong> The chapter ends the Watchers section with a final astronomical observation: the stars passing through the southern portals run their courses to the west on prescribed paths. The verse registers what the entire Watchers section has been arguing: cosmic phenomena follow appointed schedules under divine ordering, and the seer’s function is to document this ordering as theological evidence. The image of stars on prescribed paths recurs throughout Enochic literature (cf. 2:1, the chapter’s parallel; 41:5, "I saw the chambers of the sun and moon… how their work and rotation are appointed"; 43:1–2, Enoch counting all the stars by name). The chapter concludes the Book of Watchers (chs 1–36) on a note of cosmic order achieved and witnessed; the next major section (chs 37–71, the Book of Parables) will turn from cosmic observation to eschatological proclamation.""",
