        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Book of Parables (1 Enoch 37-71)</em> <small>(c. 100 BC)</small><p>&#x27;The second vision which he saw, the vision of wisdom — which Enoch the son of Jared, the son of Mahalalel...&#x27; opens the Book of Parables, the most theologically dense section of 1 Enoch. Where the Watchers material is mythological-historical, the Parables are visionary-eschatological, centering on the figure of the Son of Man as cosmic judge. The opening dating in &#x27;the days of Jared&#x27; (consistent with 6:6) anchors the Parables historically while the visionary content opens onto the eschaton. The Tewahedo reception of the Parables as canonical Scripture gives the Mäṣḥafä Hēnok its distinctive Christological-eschatological weight.</p></aside>',
