        "Tewahedo — 1 Enoch (Ethiopian tradition)",
        "1 Enoch (Ethiopian tradition) (-250).",
        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Astronomical Book (1 Enoch 72-82)</em> <small>(c. 250 BC)</small><p>&#x27;And on account of them men go wrong therein, for those luminaries truly render service on the world-stations, one in the first portal, one in the third portal of the heaven, and so on&#x27; — the polemic against calendar error. Tewahedo liturgical tradition takes this verse seriously as a warning: feast-day timing matters because the cosmic order matters. The Tewahedo Synaxarium&#x27;s precision on saint-commemoration dates (down to the specific verse of Psalm read on each day) traces theologically to this Enochic concern about getting-the-time-right.</p></aside>',
        "1 Enoch 75:2, trans. R.H. Charles (1912). PD.",
