        "1 Enoch (Ethiopian tradition) (-250).",
        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Astronomical Book (1 Enoch 72-82)</em> <small>(c. 250 BC)</small><p>&#x27;And at the ends of the earth I saw twelve portals open to all the regions, from which the winds go forth and blow over the earth&#x27; — twelve wind-portals matching the twelve solar gates. Tewahedo iconographic tradition preserves the twelve-wind imagery in some monastic-church frescoes where the cardinal-and-intermediate directions are personified as angelic figures — drawing on the Astronomical Book&#x27;s catalog of cosmic presences as canonical authority.</p></aside>',
