        "1 Enoch (Ethiopian tradition) (-250).",
        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Astronomical Book (1 Enoch 72-82)</em> <small>(c. 250 BC)</small><p>&#x27;And I saw seven mountains higher than all the mountains which are on the earth: and thence comes forth hoar-frost, and days, seasons, and years pass away. And I saw seven rivers on the earth larger than all the rivers&#x27; — sevenfold cosmic geography. Tewahedo monastic geography (the naming of seven holy mountains in Ethiopia, including Debre Damo, Debre Libanos, and the Lalibela complex) preserves the seven-mountains motif as Tewahedo holy-land cosmography, drawing on this Enochic vision.</p></aside>',
