        "1 Enoch (Ethiopian tradition) (-250).",
        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Astronomical Book (1 Enoch 72-82)</em> <small>(c. 250 BC)</small><p>&#x27;And the names of the sun are the following: the first Orjarēs, and the second Tomāsē. And the moon has four names: the first name is Asōnja, the second Eblā, the third Benāsē, and the fourth Erā&#x27; — the named luminaries. Tewahedo angelological tradition preserves the pattern of NAMED celestial beings (rather than impersonal forces): every star has a name known to Uriel and revealed to Enoch, just as every soul has a name known to its guardian angel — the personal-not-impersonal cosmos.</p></aside>',
