        "1 Enoch (Ethiopian tradition) (-250).",
        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Astronomical Book (1 Enoch 72-82)</em> <small>(c. 250 BC)</small><p>&#x27;And in the days of the sinners the years shall be shortened, and their seed shall be tardy on their lands and fields, and all things on the earth shall alter, and shall not appear in their time&#x27; — sinners&#x27; cosmic disruption. Tewahedo eschatological homilies cite this verse as the canonical warning that moral disorder shows up in cosmic disorder — drought, famine, plague — not as punitive intervention but as the natural physical consequence of broken covenant. The verse undergirds Tewahedo fasting-as-restoration theology.</p></aside>',
