        "1 Enoch (Ethiopian tradition) (-250).",
        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Astronomical Book (1 Enoch 72-82)</em> <small>(c. 250 BC)</small><p>&#x27;And I observed the heavenly tablets, and read everything which was written thereon and understood everything, and read the book of all the deeds of mankind, and of all the children of flesh that shall be upon the earth to the remotest generations&#x27; — the heavenly tablets. Tewahedo soteriology preserves the books-of-deeds image (parallel to Rev 20:12) as load-bearing in the Tewahedo last-judgment iconography, with the Enochic version emphasising that the tablets are READABLE — God&#x27;s record is transparent to inquiry.</p></aside>',
