        "Tewahedo — 1 Enoch (Ethiopian tradition)",
        "1 Enoch (Ethiopian tradition) (-250).",
        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Astronomical Book (1 Enoch 72-82)</em> <small>(c. 250 BC)</small><p>The angels who escort Enoch tell him: &#x27;Declare everything to thy son Methuselah, and show to all thy children that no flesh is righteous in the sight of the Lord, for He is their Creator&#x27; — the foundational anthropological pessimism that anticipates Pauline &#x27;all have sinned&#x27; (Rom 3:23). The Tewahedo reading connects this verse to the Romans passage explicitly: the apostolic doctrine of universal sinfulness has its Jewish-canonical basis in the Mäṣḥafä Hēnok, not introduced by Paul ex nihilo but inherited from the prophetic-apocalyptic tradition. The pessimism is grounded ontologically (&#x27;for He is their Creator&#x27; — only the Creator is finally righteous) rather than merely empirically.</p></aside>',
