        "Tewahedo — 1 Enoch (Ethiopian tradition)",
        "1 Enoch (Ethiopian tradition) (-250).",
        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Astronomical Book (1 Enoch 72-82)</em> <small>(c. 250 BC)</small><p>&#x27;And now, my son Methuselah, all these things I am recounting to thee and writing down for thee, and I have revealed to thee everything, and given thee books concerning all these: so preserve, my son Methuselah, the books from thy father&#x27;s hand, and see that thou deliver them to the generations of the world&#x27; — the textual transmission charge to Methuselah. Tewahedo monastic-scribal tradition treats this verse as the FOUNDATIONAL warrant for the entire Mäṣḥafä Hēnok preservation enterprise: the Ethiopian scribes who copied Enoch from the 4th century onward stood consciously in this Methuselan succession.</p></aside>',
