        7,
        "",
        "",
        "comm-ethiopian",
        "Tewahedo — 1 Enoch (Ethiopian tradition)",
        "1 Enoch (Ethiopian tradition) (-150).",
        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Dream Visions (1 Enoch 83-90)</em> <small>(c. 150 BC)</small><p>&#x27;I lifted up my hands and prayed and besought and spake, and said: Destroy not the earth; for I have seen the affliction of the earth, and a great destruction. And my grandfather Mahalalel said to me: Wherefore criest thou so, my son?&#x27; — Mahalalel&#x27;s question precedes his interpretation. Tewahedo catechetical tradition preserves the multi-generational form of prophetic transmission preserved here: prophecy is not a private possession but is interpreted across generations within the family-and-tradition that carries it.</p></aside>',
        "1 Enoch 83:7, trans. R.H. Charles (1912). PD.",
