        "Tewahedo — 1 Enoch (Ethiopian tradition)",
        "1 Enoch (Ethiopian tradition) (-150).",
        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Dream Visions (1 Enoch 83-90)</em> <small>(c. 150 BC)</small><p>&#x27;And I lifted up my hands in righteousness and blessed the Holy and Great One, and spake with the breath of my mouth, and with the tongue of flesh, which God has made for the children of the flesh of men, that they should speak therewith, and He gave them breath and a tongue and a mouth that they should speak therewith&#x27; — the theological warrant for prayer-with-tongue. Tewahedo liturgical theology preserves this as the canonical anchor for the doctrine that human language is GIVEN-for-praise: the tongue&#x27;s primary purpose is liturgical, not communicative.</p></aside>',
        "1 Enoch 84:1, trans. R.H. Charles (1912). PD.",
