        "plant of the eternal seed",
        "comm",
        "Note",
        "Note",
        """<strong>Petition answered by the Animal Apocalypse.</strong> Enoch petitions for preservation of "the plant of righteousness." The prayer is structurally answered when chapter 85 opens with the white bull (Adam) and the apocalypse proceeds through Noah’s deliverance and the unbroken righteous line. The "plant" metaphor for the elect community recurs throughout the Epistle of Enoch (93:2, 5, 10) and at Qumran (1QS 8:5; 1QH 14:15) — a sectarian self-designation tying back to Isaiah 60:21 and 61:3.""",
        "User original",
