        "one of them black and the other red",
        "comm-modern-critical",
        "Note",
        "Note",
        '<strong>Cain (black) and Abel (red).</strong> Color-coding signals moral character: black for wickedness, red for blood and martyrdom. The conventions hold throughout the apocalypse — white for righteous, black for wicked, red for the slaughtered righteous. The black bull "gored" the red — the same Hebrew imagery (<em>nagaḥ</em>) used in Exodus 21:28 for fatal goring oxen. Nickelsburg notes the polemical edge: moral status is visible from the start, cutting against any reading of moral indifferentism in early human history.',
        "User paraphrase; summarises Nickelsburg",
