        4,
        "",
        "",
        "comm-ethiopian",
        "Tewahedo — 1 Enoch (Ethiopian tradition)",
        "1 Enoch (Ethiopian tradition) (-150).",
        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Animal Apocalypse (1 Enoch 85-90)</em> <small>(c. 150 BC)</small><p>&#x27;And, behold, a calf was born of that white bull, and with it were born other calves, one of them white and the other black. And that first calf smote the white one and pursued him, and I saw till that white calf disappeared&#x27; — Cain (black) kills Abel (white). The allegorical structure sets up the dual-line genealogy that runs through the entire Animal Apocalypse: a white line (righteous Sethite-Noachic-Abrahamic descent) and a black line (Cainite wickedness). Tewahedo homilies on Cain/Abel preserve this colour-coded allegorical structure.</p></aside>',
