        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Animal Apocalypse (1 Enoch 85-90)</em> <small>(c. 150 BC)</small><p>&#x27;And again I saw with mine eyes as I slept, and I saw the heaven above, and behold a star fell from heaven, and it arose and ate and pastured amongst those oxen. And after that I saw the large and the black cattle&#x27; — the first star to fall in the Animal Apocalypse identifies as Asael / Azazel (the same figure judged in 1En 10:13). The allegorical concentration here recasts the entire Watchers narrative in animal-form as preface to the human historical narrative.</p></aside>',
