        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Animal Apocalypse (1 Enoch 85-90)</em> <small>(c. 150 BC)</small><p>&#x27;And again I saw in the vision, and looked towards the heaven, and behold I saw many stars descend and cast themselves down from heaven to that first star, and they became bulls amongst those cattle and pastured with them amongst them&#x27; — the 200 watchers fall as stars. Tewahedo angelic-history teaching uses 86:3 with 1En 6:5-7 (also pinned in γ.4.4.B) as the two complementary witnesses to the same event: the Watchers narrative IS the cosmological precondition for human history.</p></aside>',
