        "Note",
        "Note",
        """<strong>The four archangels.</strong> Beings "like white men" are the four archangels — Michael, Raphael, Gabriel, and Phanuel — listed in 1 Enoch 9 and 40. Three additional figures accompany them; commentators differ over their identity, but the archangelic core is unambiguous. The archangels are the agents of judgment against the Watchers and their progeny throughout chs 86–90, recapitulating the role assigned to them in chs 9–10.""",
