        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Animal Apocalypse (1 Enoch 85-90)</em> <small>(c. 150 BC)</small><p>&#x27;And I raised mine eyes again to heaven, and I saw in the vision, and behold there came forth from heaven beings who were like white men: and four went forth from that place and three with them&#x27; — the four white men are the four archangels of presence (Michael, Gabriel, Raphael, Phanuel — matching 1En 40:2-9 pinned in γ.4.4.C). The seven-archangel ecclesiology that Tewahedo preserves uniquely uses this Animal-Apocalypse vision as one of its three witnesses (with 9:1 and 20:1).</p></aside>',
