        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Animal Apocalypse (1 Enoch 85-90)</em> <small>(c. 150 BC)</small><p>&#x27;And those three that had last come forth grasped me by my hand and took me up, away from the generations of the earth, and raised me up to a lofty place, and showed me a tower raised high above the earth&#x27; — Enoch translated by three archangels to view world history from above. Tewahedo monastic-mystical tradition uses this verse as a canonical example of the contemplative ascent that the highest stages of monastic prayer approximate.</p></aside>',
