        "bound it hand and foot and cast it into an abyss",
        "comm",
        "Note",
        "Note",
        """<strong>Asael’s binding — direct reuse of Watchers narrative.</strong> The action repeats 1 Enoch 10:4–6, where Raphael binds Asael in the desert of Dudael. The repetition is deliberate: the audience is meant to identify the figures across Enochic units. The image of bound supernatural rebels in an abyss is taken up directly in Jude 6 ("the angels who did not keep their own position… kept in eternal chains in deepest darkness for the judgment of the great day") and 2 Peter 2:4 (Greek <em>Tartarōō</em>). The Aramaic Enoch fragments from Qumran (4QEnoch) attest the stable transmission of this imagery.""",
        "User paraphrase; references 1 Enoch",
