        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Animal Apocalypse (1 Enoch 85-90)</em> <small>(c. 150 BC)</small><p>&#x27;And I saw one of those four who had come forth first, and he seized that first star which had fallen from the heaven, and bound it hand and foot and cast it into an abyss: now that abyss was narrow and deep, and horrible and dark&#x27; — Asael&#x27;s binding by Michael (parallel to 10:4-6). Tewahedo demonology reads the binding-of-Azazel as a TEMPORAL binding in the cosmic narrative that culminates in the eschatological judgment at 90:24 — providing the two-stage pattern that Rev 20:1-10 follows.</p></aside>',
