        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Animal Apocalypse (1 Enoch 85-90)</em> <small>(c. 150 BC)</small><p>&#x27;And one of them drew his sword, and gave it to those elephants and camels and asses: then they began to smite each other, and the whole earth quaked because of them. And as I was beholding in the vision, lo, one of those four who had come forth, hurled (a book) from heaven, and gathered and took all the great stars whose privy members were like those of horses, and bound them all hand and foot, and cast them into an abyss of the earth&#x27; — all 200 watchers bound. The full Watchers-judgment scene preserved in the Animal Apocalypse as one of its inaugurating actions, before human history proper begins.</p></aside>',
