        "instructed him in a secret",
        "comm",
        "Note",
        "Note",
        """<strong>Noah and the ark.</strong> The white bull (Noah, here "born a bull and became a man") builds "a great vessel" — the ark. The detail that Noah is transformed encodes the elevated view of the patriarch characteristic of Second Temple Judaism (Jubilees 5–10 makes him a major patriarch and law-giver, recipient of Noachide commandments). The transformation marks Noah as the new founding figure after the antediluvian world is purged, parallel to the bull-to-man transformation Moses will undergo at 89:36.""",
        "User paraphrase; references Jubilees",
