        "1 Enoch (Ethiopian tradition) (-150).",
        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Animal Apocalypse (1 Enoch 85-90)</em> <small>(c. 150 BC)</small><p>&#x27;And one of those four went to that white bull and instructed him in a secret, without his being terrified: he was born a bull and became a man, and built for himself a great vessel and dwelt thereon; and three bulls dwelt with him in that vessel&#x27; — Noah translated from BULL to MAN (rare ontological-elevation in the allegory). The transformation is theologically loaded: a righteous human in the Animal Apocalypse can be REMADE-into-something-higher. Tewahedo deification theology cites this as the canonical precedent (with Enoch&#x27;s transfiguration at 71:11) for the doctrine of theosis as ontological-not-merely-moral transformation.</p></aside>',
