        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Animal Apocalypse (1 Enoch 85-90)</em> <small>(c. 150 BC)</small><p>&#x27;And those three that came forth, and all the (four) cattle came with them: and amongst them was a white bull and a red, like a wild ass&#x27; — Noah&#x27;s three sons as bulls (Shem white, Ham black, Japheth red — the common Tewahedo identification matching the table of nations of Gen 10). Tewahedo genealogical tradition preserves the Hamitic identification of Ethiopia (descent from Cush son of Ham) but reads it WITHOUT the curse-of-Ham racialisation that Western Christianity often imposed: in Tewahedo reading, the colour-coding in 89:9 is allegorical, not ethnic.</p></aside>',
