        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Animal Apocalypse (1 Enoch 85-90)</em> <small>(c. 150 BC)</small><p>&#x27;And those (cattle) began to be born among them and to multiply: and they were divided amongst themselves into species&#x27; — the table-of-nations moment. Tewahedo ethnogenesis-teaching (preserved in the Kebra Nagast and in monastic genealogical chronicles) traces all peoples to legitimate divine ordering — the multiplication-and-division of peoples is positive, not curse-driven, anchoring an anti-supremacist Tewahedo theological anthropology.</p></aside>',
