        "Note",
        "Note",
        "<strong>The twelve sons of Jacob.</strong> Twelve sheep born from one sheep (Jacob) — the foundation of the twelve-tribe structure of Israel. The shift from bovines to ovines for the covenant people occurs precisely here: Jacob is the first sheep, his twelve sons confirming the new schema. Black wild boars descended from Esau (also at 89:12) carry Edomite hostility forward, an enmity that recurs throughout the apocalypse and in much of Second Temple literature (compare Jubilees 38; the targumim).",
        "User paraphrase; references Jubilees, targumim",
