        "Tewahedo — 1 Enoch (Ethiopian tradition)",
        "1 Enoch (Ethiopian tradition) (-150).",
        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Animal Apocalypse (1 Enoch 85-90)</em> <small>(c. 150 BC)</small><p>&#x27;And the white bull begat a wild ass, and a white bull with it: and the wild ass multiplied. But that bull which was born from him begat a black wild boar and a white sheep&#x27; — Abraham (white bull) begets Ishmael (wild ass) and Isaac (white bull); Isaac then begets Esau (black wild boar) and Jacob (white sheep). The sheep-as-Israel allegory begins here. Tewahedo ecclesiology preserves the sheep-of-the-flock identification through the Anaphora of the Apostles (where &#x27;sheep of Thy pasture&#x27; resonates with this Animal-Apocalypse imagery).</p></aside>',
