        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Animal Apocalypse (1 Enoch 85-90)</em> <small>(c. 150 BC)</small><p>&#x27;And the descendants of that white bull begat twelve sheep, and those twelve sheep were given over into the hand of dogs&#x27; — the twelve sons of Jacob given over to oppressors (sold-into-Egypt allegory) but already preserving the sheep-as-the-twelve-tribes identification. Tewahedo reading of Israel-Egypt history through this Enochic allegorical lens preserves a distinctive emphasis: the sheep-shape of God&#x27;s people is eternal; the form persists through every oppression.</p></aside>',
