        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Animal Apocalypse (1 Enoch 85-90)</em> <small>(c. 150 BC)</small><p>&#x27;And those sheep ascended and came to a house, and the Lord of the sheep stood upon it. And all the sheep prostrated themselves before Him: I saw all the sheep gathered together and bowing down before the throne&#x27; — Sinai theophany: the wilderness tabernacle as &#x27;house&#x27; for the sheep. Tewahedo tabot-theology (the tablets-in-the-ark as the abiding presence) draws on 89:36 as scriptural anchor: the house-of-the-sheep is where the Lord-of-the-sheep dwells, transferring from wilderness tabernacle to Tewahedo qǝddǝst-qǝddusan (holy of holies) by continuous succession.</p></aside>',
