        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Animal Apocalypse (1 Enoch 85-90)</em> <small>(c. 150 BC)</small><p>&#x27;And the dogs began to rend, and the foxes to devour, and the wild boars to eat the sheep, until the Lord of the sheep raised up a ram from amongst them, who led them&#x27; — gentile oppressors as dogs (Philistines), foxes (Ammonites), wild boars (Edomites/Amalekites); the ram raised up is Samuel (or Saul). Tewahedo homiletics on the Judges-Samuel narrative preserves the allegorical-spiritual reading alongside the historical: every oppression is also a spiritual war.</p></aside>',
