        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Animal Apocalypse (1 Enoch 85-90)</em> <small>(c. 150 BC)</small><p>&#x27;And the sheep increased and multiplied: and all those dogs, and foxes, and wild boars feared and fled before them, and that ram pushed and killed the wild beasts: and they had no more power amongst the sheep, and robbed them no more of ought. And that house became great and broad, and a high tower was built upon the house&#x27; — David / Solomon era: the house grows great, the tower (TEMPLE) is built upon it. Tewahedo ecclesiology preserves the tower-on-house imagery (church-on-Christ-the-rock, with the temple as eschatological prefiguration of the Tewahedo qǝddǝst) as the canonical anticipation of the ecclesial structure.</p></aside>',
