        "1 Enoch (Ethiopian tradition) (-150).",
        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Animal Apocalypse (1 Enoch 85-90)</em> <small>(c. 150 BC)</small><p>&#x27;And He gave them over into the hands of the lions and tigers, and wolves and hyenas, and into the hand of the foxes, and to all the wild beasts: and those wild beasts began to tear those sheep in pieces. And He forsook the house of their fathers, and their tower, and gave them all into the hand of the lions, to tear and devour them&#x27; — the Babylonian exile: the tower is forsaken, the sheep given to lions (Babylon). Tewahedo exilic-theology preserves the lesson: when the house-of-the-Lord becomes empty, God&#x27;s people are scattered. The Tewahedo preservation of Solomon&#x27;s-temple-tradition through the ark-narrative is read as the providential antidote.</p></aside>',
