        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Animal Apocalypse (1 Enoch 85-90)</em> <small>(c. 150 BC)</small><p>&#x27;And He called seventy shepherds, and cast those sheep to them that they might pasture them, and He spake to the shepherds and their companions: Let each individual of you pasture the sheep henceforward, and everything that I shall command you that do ye&#x27; — the seventy shepherds period (from exile to eschaton, the period of gentile dominion). Tewahedo reading interprets the seventy as covering the entire intertestamental and Greco-Roman period: the time when God&#x27;s people are RULED by foreign shepherds. The 70 cycle echoes Jer 25:11-12 / Dan 9:24-27 but spans a longer epoch.</p></aside>',
