        "shepherds and their associates delivered over those sheep",
        "comm",
        "Note",
        "Note",
        """<strong>The seventy shepherds — the angelic schema of history.</strong> The defining numerological feature of the Animal Apocalypse: 70 angelic overseers, 7 × 10, a totalizing figure for "all angelic overseers across history." Each shepherd has a fixed period to pasture the sheep (Israel) until judgment. Olson reads the seventy as spanning from the destruction of the First Temple to the eschatological consummation; the schema parallels Daniel 9’s seventy weeks. The heavenly shepherd is a widespread ANE motif (Tammuz, Marduk’s shepherding functions); 1 Enoch domesticates it within angelology, making each shepherd accountable to the Lord of the sheep — and ultimately judged at 90:25.""",
