        "they began again to build",
        "comm",
        "Note",
        "Note",
        """<strong>Critique of the rebuilt Second Temple.</strong> The rebuilt Second Temple (Zerubbabel’s, c. 515 BCE) is judged "polluted" from its inception — "all the bread on it was polluted and was not pure" (89:73). The Enochic community evidently held a sectarian view rejecting the legitimacy of post-exilic temple worship, anticipating the Qumran community’s more elaborate temple-rejection (1QpHab; 4QMMT). This is decisive for dating: the Animal Apocalypse must postdate the rebuilt temple, and its sharp critique places the work in a proto-sectarian milieu well before Qumran’s consolidation.""",
