        "Note",
        """<strong>The shepherd schema continues.</strong> The full sequence is 12 + 23 + 23 + 12 = 70 shepherds, structured around four periods of foreign domination (Babylonian, Persian, Hellenistic, late-Hellenistic / Maccabean). The author writes from inside the fourth period, the last twelve. The historical fingerprint points to the early Maccabean era (mid-second century BCE). Compare the alternative periodization in the Apocalypse of Weeks (1 En 93:3–10 + 91:11–17), which divides history into ten weeks rather than four sets of shepherds.""",
