        "lambs were borne by those white sheep",
        "comm",
        "Note",
        "Note",
        """<strong>The Hasidim and the Maccabean revolt.</strong> The "lambs" born to the white sheep that "begin to open their eyes" are widely identified with the Hasidim or proto-Maccabean reformers — a faithful remnant who "see" the apostasy of mainstream Judaism. The lambs’ growing horns (90:9) escalate to a single great-horned ram, almost universally read as Judas Maccabeus. The chapter is therefore one of the most precisely datable Jewish apocalyptic compositions: c. 165–160 BCE, before Judas’s death in 160, since he is depicted as triumphant rather than martyred.""",
