        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Animal Apocalypse (1 Enoch 85-90)</em> <small>(c. 150 BC)</small><p>&#x27;But behold lambs were borne by those white sheep, and they began to open their eyes and to see, and to cry to the sheep&#x27; — the awakening of the lambs (the Hasidic/early-Maccabean reformist movement, the small remnant who saw the apostasy and cried out). Tewahedo monastic-reform history (the multiple movements of monastic renewal in Ethiopian church history) draws typological parallels to 90:6: the small remnant that opens its eyes is the canonical pattern of every spiritual renewal.</p></aside>',
