        "horns grew upon those lambs",
        "comm-modern-critical",
        "Note",
        "Note",
        "<strong>The horn imagery and the Maccabean ram.</strong> Horn imagery has biblical precedent in Daniel 7–8 and Ezekiel 29:21, where horns symbolize royal-military strength. Here, multiple lambs growing horns culminates in one great-horned ram leading the rest — best identified with Judas Maccabeus. The Animal Apocalypse functions as militant resistance literature, coding the Maccabean revolt as participation in the eschatological war of the Lord of the sheep. Tiller and Nickelsburg agree on the Judas identification; some details of the lamb’s rise are obscure, but the broad picture is firm.",
        "User paraphrase; summarises Nickelsburg",
