        "comm-ethiopian",
        "Tewahedo — 1 Enoch (Ethiopian tradition)",
        "1 Enoch (Ethiopian tradition) (-150).",
        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Animal Apocalypse (1 Enoch 85-90)</em> <small>(c. 150 BC)</small><p>&#x27;And I saw till that horns grew upon those lambs, and the ravens cast down their horns; and I saw till there sprouted a great horn of one of those sheep&#x27; — the rise of Judas Maccabeus as the &#x27;great horn&#x27; in the Animal Apocalypse&#x27;s symbolic history. Charles dates the composition of this section to the Maccabean revolt (~165 BC), making it nearly-contemporary historical commentary in apocalyptic form. The verse establishes the Animal Apocalypse&#x27;s prophetic-now character: it reads contemporary events as the unfolding of the cosmic drama. The Tewahedo reception preserves this prophetic-historical reading mode, applied throughout the medieval period to Ethiopian historical events.</p></aside>',
        "1 Enoch 90:9, trans. R.H. Charles (1912). PD.",
