        "1 Enoch (Ethiopian tradition) (-150).",
        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Animal Apocalypse (1 Enoch 85-90)</em> <small>(c. 150 BC)</small><p>&#x27;And I saw till that man, who wrote down the names of the shepherds and carried them up before the Lord of the sheep, came and helped that ram and showed him everything: his help came down&#x27; — the angelic scribe-intercessor helps the Maccabean leader. Tewahedo angelic-mediation theology preserves this image of the heavenly-scribe-who-records-and-intervenes (essentially identical to the role given Michael/Phanuel in other Enochic strata).</p></aside>',
