        "Note",
        """<strong>The theophanic judgment.</strong> The Lord of the sheep arrives in person, takes "the staff of His wrath," and smites the earth — the climactic theophany that ends the historical schema. Direct divine judgment, unmediated by archangel or shepherd, is the apocalyptic resolution: the angelic-shepherd system that has structured all of history (89:59 onward) is suspended for direct sovereign action. Compare Isaiah 63:1–6 and Revelation 19:11–16 for parallel "warrior-Lord" theophanies that conclude historical suffering.""",
