        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Animal Apocalypse (1 Enoch 85-90)</em> <small>(c. 150 BC)</small><p>&#x27;And I saw till a throne was erected in the pleasant land, and the Lord of the sheep sat Himself thereon, and the other took the sealed books and opened those books before the Lord of the sheep&#x27; — the eschatological throne of judgment with the books opened. Direct verbal preparation for Dan 7:9-10 and Rev 20:11-12; the Tewahedo eschatological-judgment iconography preserves the books-before-the-throne as load-bearing in Mäṣḥafä Berhan (Book of Light) tradition.</p></aside>',
