        "1 Enoch (Ethiopian tradition) (-150).",
        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Animal Apocalypse (1 Enoch 85-90)</em> <small>(c. 150 BC)</small><p>&#x27;And the judgment was held first over the stars, and they were judged and found guilty, and went to the place of condemnation, and they were cast into an abyss, full of fire and flaming, and full of pillars of fire&#x27; — final judgment of the fallen watchers (the long-anticipated eschatological reckoning, complementing their preliminary binding at 10:4-6 and 88:1-3). Tewahedo demonology reads the two-stage pattern (binding now, fire-judgment at eschaton) as the canonical model: evil is RESTRAINED but not yet FINALLY DESTROYED in the present age.</p></aside>',
