        "1 Enoch (Ethiopian tradition) (-150).",
        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Animal Apocalypse (1 Enoch 85-90)</em> <small>(c. 150 BC)</small><p>&#x27;And I stood up to see till they folded up that old house; and carried off all the pillars, and all the beams and ornaments of the house were at the same time folded up with it, and they carried it off and laid it in a place in the south of the land. And I saw till the Lord of the sheep brought a new house greater and loftier than that first, and set it up in the place of the first which had been folded up: all its pillars were new, the columns new; and the ornaments new and larger than those of the first, the old one which He had taken away, and all the sheep were within it&#x27; — the new Jerusalem / new house replacing the old. Tewahedo eschatology reads this verse as direct anticipation of Rev 21:2-3 (new Jerusalem descending), with the Tewahedo distinctive emphasis that the new house is GREATER than the first — escalation, not mere restoration.</p></aside>',
