        3,
        "",
        "this is the end of the second Parable",
        "comm",
        "Note",
        "Note",
        """<strong>End of the Second Parable.</strong> The explicit structural marker closes the longest of the three parables. Such self-naming editorial signposts are rare in Jewish apocalyptic literature; their presence here helps confirm that the three-parable division of chs 38–69 is not a later editorial imposition but reflects the original compositional intent. The Third Parable (chs 58–69) follows immediately, with its own opening signpost at 58:1.""",
        "User original",
