    (
        95,
        6,
        "",
        "Woe to you, lying witnesses",
        "comm",
        "Note",
        "Note",
        """<strong>False witness.</strong> The Decalogue prohibition (Exod 20:16; Deut 5:20) is taken up as a category of apocalyptic woe. False witness is paired with “those who weigh out injustice” — combining judicial corruption with commercial fraud. The pairing reflects a thoroughgoing critique of the social-economic-judicial order that perpetuates injustice. James 5:1–6 (“Come now, you rich, weep and howl… your gold and silver have rusted… behold, the wages of the laborers… you have condemned and murdered the righteous”) echoes this exact rhetorical complex.""",
        "User original",
    ),
    (
        96,
        1,
        "",
        "Be hopeful, ye righteous; for suddenly shall the sinners perish",
        "comm",
        "Note",
        "Note",
        """<strong>Encouragement formula.</strong> The phrase “Be hopeful” punctuates the Epistle as a refrain (also at 102:4; 104:2, 4; 108:8). It functions liturgically — a call-and-response between the lament-woes against the wicked and the hope-encouragements to the righteous. The encouragement-genre passes into the New Testament epistles (1 Thess 4:18 “encourage one another with these words”; 2 Thess 2:17). The Epistle of Enoch establishes the pattern of pairing apocalyptic warning with pastoral encouragement.""",
        "User original",
    ),
