        "comm-ethiopian",
        "Tewahedo — 1 Enoch (Ethiopian tradition)",
        "1 Enoch (Ethiopian tradition) (-100).",
        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Epistle of Enoch (1 Enoch 91-108)</em> <small>(c. 100 BC)</small><p>&#x27;Be hopeful, ye righteous; for suddenly shall the sinners perish before you, and ye shall have lordship over them according to your desires&#x27; — the hope-oracle counterpart to the woe oracles. Tewahedo hope-theology (persecution-resilience preserved through Aksum-era persecutions, Gragn invasion, the Derg-era massacres of monks) draws on this Enochic hope-formula: present suffering does not falsify the eschatological reversal.</p></aside>',
        "1 Enoch 96:1, trans. R.H. Charles (1912). PD.",
