        "",
        "comm-ethiopian",
        "Tewahedo — 1 Enoch (Ethiopian tradition)",
        "1 Enoch (Ethiopian tradition) (-100).",
        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Epistle of Enoch (1 Enoch 91-108)</em> <small>(c. 100 BC)</small><p>&#x27;Be hopeful, therefore, ye who have suffered tribulation; for ye shall have great joy as the angels of heaven&#x27; — equal-to-the-angels promise. Tewahedo monastic spirituality reads this verse as the canonical anchor for the doctrine that the eschatological state of the saints is angelic-in-rank — parallel to Lk 20:35-36 (&#x27;equal unto the angels&#x27;) and 1 Cor 15:48-49.</p></aside>',
