        "comm-ethiopian",
        "Tewahedo — 1 Enoch (Ethiopian tradition)",
        "1 Enoch (Ethiopian tradition) (-100).",
        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Epistle of Enoch (1 Enoch 91-108)</em> <small>(c. 100 BC)</small><p>&#x27;Woe to you who acquire silver and gold in unrighteousness and say: We have become rich with riches and have possessions; and have acquired everything we have desired. And now let us do what we purposed: for we have gathered silver, and many are the husbandmen in our houses&#x27; — woe oracle against acquisitive wealth. Direct verbal-thematic anticipation of the Lukan parable of the rich fool (Lk 12:16-21). Tewahedo monastic tradition of voluntary poverty roots theologically in the Enochic woe-oracle stream.</p></aside>',
        "1 Enoch 97:8, trans. R.H. Charles (1912). PD.",
