        "1 Enoch (Ethiopian tradition) (-100).",
        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Epistle of Enoch (1 Enoch 91-108)</em> <small>(c. 100 BC)</small><p>&#x27;And in those days the angels shall descend into the secret places and gather together into one place all those who brought down sin, and the Most High will arise on that day of judgement to execute great judgement amongst sinners&#x27; — angelic descent for the gathering-of-sinners. Tewahedo angelological tradition reads this verse alongside Mt 13:39-41 (&#x27;the harvesters are angels... they shall gather out of his kingdom all things that offend&#x27;) as direct Enochic precedent for the Synoptic image.</p></aside>',
