        "",
        "",
        "comm-ethiopian",
        "Tewahedo — 1 Enoch (Ethiopian tradition)",
        "1 Enoch (Ethiopian tradition) (-100).",
        '<aside class="note-comm-ethiopian"><strong>1 Enoch (Ethiopian tradition)</strong> <em>Epistle of Enoch (1 Enoch 91-108)</em> <small>(c. 100 BC)</small><p>&#x27;Woe to you, sinners, on the day of strong anguish, ye who afflict the righteous and burn them with fire: ye shall be requited according to your works&#x27; — woe oracle for those who burn the righteous (allusion to martyrdom). Tewahedo martyrological tradition (the long history of Ethiopian Christian martyrdom under Aksum-era pagan reversions, Beta Israel/Falasha tensions, Mahdist invasions, modern persecutions) reads this verse as the eschatological vindication-promise for every named martyr.</p></aside>',
